-- GREAT LAKE STATE KEEPERS — PHASE 2 SUPPLEMENTAL DRAFT + ROOKIE RIGHTS
-- Version 9. Safe migration: DOES NOT reset the Phase 1 auction, team budgets, PINs, bids or sales.
-- Run in Supabase SQL Editor using "Run without RLS".

begin;

-- ---------------------------------------------------------------------------
-- Phase 1 rookie-rights transfer support
-- ---------------------------------------------------------------------------
alter table public.players add column if not exists rights_team_id uuid references public.teams(id);

create table if not exists public.auction_rights_transfers (
  id bigint generated by default as identity primary key,
  room_id uuid not null references public.rooms(id) on delete cascade,
  player_id uuid not null references public.players(id),
  from_team_id uuid not null references public.teams(id),
  to_team_id uuid not null references public.teams(id),
  price integer not null check (price > 0),
  transferred_at timestamptz not null default now()
);
alter table public.auction_rights_transfers enable row level security;
drop policy if exists "public read auction rights transfers" on public.auction_rights_transfers;
create policy "public read auction rights transfers" on public.auction_rights_transfers for select to anon, authenticated using (true);
grant select on public.auction_rights_transfers to anon, authenticated;
revoke insert, update, delete on public.auction_rights_transfers from anon, authenticated;

-- Top-40 rookie rights confirmed by commissioner.
update public.players p set rights_team_id = t.id
from public.teams t, public.rooms r
where p.room_id=r.id and t.room_id=r.id and r.code='GLSK26' and
 ((p.name='Omarion Hampton' and t.name='MEGATRONS V2') or
  (p.name='Colston Loveland' and t.name='hugs not drugs') or
  (p.name='Tyler Warren' and t.name='Reggie Kush') or
  (p.name='Cam Skattebo' and t.name='kerwinning it') or
  (p.name='Quinshon Judkins' and t.name='Suburban White Kid') or
  (p.name='Bhayshul Tuten' and t.name='The Real McCoy'));

create or replace function public.commish_transfer_rookie_rights(
  p_room_code text, p_commish_pin text, p_player_id uuid
) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare
  v_room public.rooms%rowtype;
  v_player public.players%rowtype;
  v_sale public.sales%rowtype;
  v_from public.teams%rowtype;
  v_to public.teams%rowtype;
begin
  select * into v_room from public.rooms where code=p_room_code for update;
  if v_room.id is null or not public._valid_commish_pin(v_room.id,p_commish_pin) then
    return jsonb_build_object('ok',false,'error','Commissioner authorization failed.');
  end if;
  select * into v_player from public.players where id=p_player_id and room_id=v_room.id for update;
  if v_player.id is null or v_player.status<>'sold' then return jsonb_build_object('ok',false,'error','That player is not currently sold.'); end if;
  if v_player.rights_team_id is null then return jsonb_build_object('ok',false,'error','No rookie-rights holder is assigned to this player.'); end if;
  select * into v_sale from public.sales where room_id=v_room.id and player_id=v_player.id and undone=false order by sold_at desc limit 1 for update;
  if v_sale.id is null then return jsonb_build_object('ok',false,'error','Active sale record not found.'); end if;
  if v_sale.team_id=v_player.rights_team_id then return jsonb_build_object('ok',false,'error','The rights holder already owns this player.'); end if;
  select * into v_from from public.teams where id=v_sale.team_id for update;
  select * into v_to from public.teams where id=v_player.rights_team_id for update;
  if v_to.remaining_budget < v_sale.price then return jsonb_build_object('ok',false,'error',v_to.name || ' does not have enough bid dollars for this claim.'); end if;
  update public.teams set remaining_budget=remaining_budget+v_sale.price where id=v_from.id;
  update public.teams set remaining_budget=remaining_budget-v_sale.price where id=v_to.id;
  update public.players set sold_team_id=v_to.id where id=v_player.id;
  update public.sales set team_id=v_to.id where id=v_sale.id;
  insert into public.auction_rights_transfers(room_id,player_id,from_team_id,to_team_id,price)
  values(v_room.id,v_player.id,v_from.id,v_to.id,v_sale.price);
  return jsonb_build_object('ok',true,'player',v_player.name,'from_team',v_from.name,'to_team',v_to.name,'price',v_sale.price);
end; $$;
grant execute on function public.commish_transfer_rookie_rights(text,text,uuid) to anon,authenticated;

-- ---------------------------------------------------------------------------
-- Supplemental draft schema
-- ---------------------------------------------------------------------------
create table if not exists public.supplemental_players (
  id uuid primary key default gen_random_uuid(),
  room_id uuid not null references public.rooms(id) on delete cascade,
  yahoo_rank integer not null,
  name text not null,
  nfl_team text not null,
  position text not null check(position in ('QB','RB','WR','TE','K','DST')),
  pos_rank integer,
  bye integer,
  projection_stats jsonb not null default '{}'::jsonb,
  ranking_source text,
  projection_source text,
  rights_team_id uuid references public.teams(id),
  status text not null default 'available' check(status in ('available','drafted')),
  drafted_team_id uuid references public.teams(id),
  drafted_price integer,
  unique(room_id,yahoo_rank,name)
);

create table if not exists public.supplemental_settings (
  room_id uuid primary key references public.rooms(id) on delete cascade,
  status text not null default 'setup' check(status in ('setup','live','paused','complete')),
  rounds integer not null default 2 check(rounds between 1 and 10),
  pick_seconds integer not null default 45 check(pick_seconds between 5 and 600),
  challenge_seconds integer not null default 10 check(challenge_seconds between 3 and 120),
  auction_seconds integer not null default 30 check(auction_seconds between 5 and 300),
  current_pick_no integer not null default 1 check(current_pick_no > 0),
  stage text not null default 'pick' check(stage in ('pick','challenge','auction','rights_auction','complete')),
  stage_ends_at timestamptz,
  pause_remaining_seconds integer,
  selected_player_id uuid references public.supplemental_players(id),
  selected_by_team_id uuid references public.teams(id),
  active_bid integer not null default 0 check(active_bid >= 0),
  active_bidder_team_id uuid references public.teams(id),
  updated_at timestamptz not null default now()
);

create table if not exists public.supplemental_order (
  room_id uuid not null references public.rooms(id) on delete cascade,
  slot integer not null check(slot between 1 and 64),
  team_id uuid not null references public.teams(id),
  primary key(room_id,slot),
  unique(room_id,team_id)
);

create table if not exists public.supplemental_picks (
  id bigint generated by default as identity primary key,
  room_id uuid not null references public.rooms(id) on delete cascade,
  pick_no integer not null,
  round integer not null,
  selecting_team_id uuid not null references public.teams(id),
  player_id uuid not null references public.supplemental_players(id),
  winner_team_id uuid not null references public.teams(id),
  price integer not null check(price >= 0),
  outcome text not null check(outcome in ('free','open_auction','rights_auction')),
  created_at timestamptz not null default now(),
  unique(room_id,pick_no)
);

create table if not exists public.supplemental_bids (
  id bigint generated by default as identity primary key,
  room_id uuid not null references public.rooms(id) on delete cascade,
  pick_no integer not null,
  player_id uuid not null references public.supplemental_players(id),
  team_id uuid not null references public.teams(id),
  amount integer not null check(amount > 0),
  kind text not null check(kind in ('open','rights')),
  created_at timestamptz not null default now()
);

create index if not exists supplemental_players_room_status_idx on public.supplemental_players(room_id,status,yahoo_rank);
create index if not exists supplemental_picks_room_pick_idx on public.supplemental_picks(room_id,pick_no);
create index if not exists supplemental_bids_room_created_idx on public.supplemental_bids(room_id,created_at desc);

alter table public.supplemental_players enable row level security;
alter table public.supplemental_settings enable row level security;
alter table public.supplemental_order enable row level security;
alter table public.supplemental_picks enable row level security;
alter table public.supplemental_bids enable row level security;

drop policy if exists "public read supplemental players" on public.supplemental_players;
drop policy if exists "public read supplemental settings" on public.supplemental_settings;
drop policy if exists "public read supplemental order" on public.supplemental_order;
drop policy if exists "public read supplemental picks" on public.supplemental_picks;
drop policy if exists "public read supplemental bids" on public.supplemental_bids;
create policy "public read supplemental players" on public.supplemental_players for select to anon,authenticated using(true);
create policy "public read supplemental settings" on public.supplemental_settings for select to anon,authenticated using(true);
create policy "public read supplemental order" on public.supplemental_order for select to anon,authenticated using(true);
create policy "public read supplemental picks" on public.supplemental_picks for select to anon,authenticated using(true);
create policy "public read supplemental bids" on public.supplemental_bids for select to anon,authenticated using(true);

grant select on public.supplemental_players,public.supplemental_settings,public.supplemental_order,public.supplemental_picks,public.supplemental_bids to anon,authenticated;
revoke insert,update,delete on public.supplemental_players,public.supplemental_settings,public.supplemental_order,public.supplemental_picks,public.supplemental_bids from anon,authenticated;

insert into public.supplemental_settings(room_id,pick_seconds,challenge_seconds,auction_seconds)
select id,45,10,30 from public.rooms where code='GLSK26'
on conflict(room_id) do update set pick_seconds=excluded.pick_seconds,challenge_seconds=excluded.challenge_seconds,auction_seconds=excluded.auction_seconds;

-- Preloaded Round 1 order; Round 2 is automatically reversed by the snake helper.
delete from public.supplemental_order where room_id=(select id from public.rooms where code='GLSK26');
insert into public.supplemental_order(room_id,slot,team_id)
select r.id,x.slot,t.id from public.rooms r
join (values
 (1,'Klyde Frogs'),(2,'Slim Charles'),(3,'hugs not drugs'),(4,'The Real McCoy'),
 (5,'Suburban White Kid'),(6,'Weiss Tea & Lemonade'),(7,'kerwinning it'),(8,'7th Floor Crew'),
 (9,'Team Ramrod'),(10,'Reggie Kush'),(11,'MEGATRONS V2'),(12,'The Hebrew Hammer')
) x(slot,team_name) on true
join public.teams t on t.room_id=r.id and t.name=x.team_name
where r.code='GLSK26';

