-- ---------------------------------------------------------------------------
-- Supplemental helpers / RPCs
-- ---------------------------------------------------------------------------
create or replace function public._supp_team_for_pick(p_room_id uuid,p_pick_no integer)
returns uuid language plpgsql stable security definer set search_path=public,pg_temp as $$
declare v_round integer; v_pos integer; v_slot integer; v_team uuid;
begin
  v_round := ((p_pick_no-1)/12)+1;
  v_pos := ((p_pick_no-1)%12)+1;
  v_slot := case when mod(v_round,2)=1 then v_pos else 13-v_pos end;
  select team_id into v_team from public.supplemental_order where room_id=p_room_id and slot=v_slot;
  return v_team;
end; $$;

create or replace function public._supp_advance(p_room_id uuid)
returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare v_s public.supplemental_settings%rowtype; v_max integer;
begin
  select * into v_s from public.supplemental_settings where room_id=p_room_id for update;
  v_max := v_s.rounds * 12;
  if v_s.current_pick_no >= v_max then
    update public.supplemental_settings set status='complete',stage='complete',stage_ends_at=null,pause_remaining_seconds=null,selected_player_id=null,selected_by_team_id=null,active_bid=0,active_bidder_team_id=null,updated_at=now() where room_id=p_room_id;
  else
    update public.supplemental_settings set current_pick_no=current_pick_no+1,stage='pick',stage_ends_at=now()+make_interval(secs=>pick_seconds),pause_remaining_seconds=null,selected_player_id=null,selected_by_team_id=null,active_bid=0,active_bidder_team_id=null,updated_at=now() where room_id=p_room_id;
  end if;
end; $$;

create or replace function public.supp_commish_start(p_room_code text,p_commish_pin text)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_room uuid; v_s public.supplemental_settings%rowtype;
begin
  select id into v_room from public.rooms where code=p_room_code;
  if v_room is null or not public._valid_commish_pin(v_room,p_commish_pin) then return jsonb_build_object('ok',false,'error','Commissioner authorization failed.'); end if;
  select * into v_s from public.supplemental_settings where room_id=v_room for update;
  if v_s.status='complete' then return jsonb_build_object('ok',false,'error','Supplemental draft is complete. Reset it before starting again.'); end if;
  update public.supplemental_settings set status='live',stage='pick',stage_ends_at=now()+make_interval(secs=>pick_seconds),pause_remaining_seconds=null,updated_at=now() where room_id=v_room;
  return jsonb_build_object('ok',true);
end; $$;

create or replace function public.supp_commish_pause(p_room_code text,p_commish_pin text)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_room uuid; v_s public.supplemental_settings%rowtype; v_rem integer;
begin
  select id into v_room from public.rooms where code=p_room_code;
  if v_room is null or not public._valid_commish_pin(v_room,p_commish_pin) then return jsonb_build_object('ok',false,'error','Commissioner authorization failed.'); end if;
  select * into v_s from public.supplemental_settings where room_id=v_room for update;
  if v_s.status<>'live' then return jsonb_build_object('ok',false,'error','Supplemental draft is not live.'); end if;
  v_rem := greatest(0,ceil(extract(epoch from (v_s.stage_ends_at-now())))::integer);
  update public.supplemental_settings set status='paused',pause_remaining_seconds=v_rem,stage_ends_at=null,updated_at=now() where room_id=v_room;
  return jsonb_build_object('ok',true);
end; $$;

create or replace function public.supp_commish_resume(p_room_code text,p_commish_pin text)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_room uuid; v_s public.supplemental_settings%rowtype; v_rem integer;
begin
  select id into v_room from public.rooms where code=p_room_code;
  if v_room is null or not public._valid_commish_pin(v_room,p_commish_pin) then return jsonb_build_object('ok',false,'error','Commissioner authorization failed.'); end if;
  select * into v_s from public.supplemental_settings where room_id=v_room for update;
  if v_s.status<>'paused' then return jsonb_build_object('ok',false,'error','Supplemental draft is not paused.'); end if;
  v_rem := greatest(1,coalesce(v_s.pause_remaining_seconds,v_s.pick_seconds));
  update public.supplemental_settings set status='live',stage_ends_at=now()+make_interval(secs=>v_rem),pause_remaining_seconds=null,updated_at=now() where room_id=v_room;
  return jsonb_build_object('ok',true);
end; $$;

create or replace function public.supp_commish_add_time(p_room_code text,p_commish_pin text,p_seconds integer default 30)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_room uuid; v_s public.supplemental_settings%rowtype; v_add integer;
begin
  select id into v_room from public.rooms where code=p_room_code;
  if v_room is null or not public._valid_commish_pin(v_room,p_commish_pin) then return jsonb_build_object('ok',false,'error','Commissioner authorization failed.'); end if;
  v_add:=greatest(1,least(coalesce(p_seconds,30),600));
  select * into v_s from public.supplemental_settings where room_id=v_room for update;
  if v_s.status='paused' then update public.supplemental_settings set pause_remaining_seconds=coalesce(pause_remaining_seconds,0)+v_add,updated_at=now() where room_id=v_room;
  elsif v_s.status='live' then update public.supplemental_settings set stage_ends_at=coalesce(stage_ends_at,now())+make_interval(secs=>v_add),updated_at=now() where room_id=v_room;
  else return jsonb_build_object('ok',false,'error','Draft must be live or paused to add time.'); end if;
  return jsonb_build_object('ok',true);
end; $$;

create or replace function public.supp_commish_update_settings(p_room_code text,p_commish_pin text,p_pick_seconds integer,p_challenge_seconds integer,p_auction_seconds integer)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_room uuid;
begin
  select id into v_room from public.rooms where code=p_room_code;
  if v_room is null or not public._valid_commish_pin(v_room,p_commish_pin) then return jsonb_build_object('ok',false,'error','Commissioner authorization failed.'); end if;
  if p_pick_seconds not between 5 and 600 or p_challenge_seconds not between 3 and 120 or p_auction_seconds not between 5 and 300 then return jsonb_build_object('ok',false,'error','One or more timer values are outside the allowed range.'); end if;
  update public.supplemental_settings set pick_seconds=p_pick_seconds,challenge_seconds=p_challenge_seconds,auction_seconds=p_auction_seconds,updated_at=now() where room_id=v_room;
  return jsonb_build_object('ok',true);
end; $$;

create or replace function public.supp_commish_set_order(p_room_code text,p_commish_pin text,p_team_ids jsonb)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_room uuid; v_count integer; v_distinct integer;
begin
  select id into v_room from public.rooms where code=p_room_code;
  if v_room is null or not public._valid_commish_pin(v_room,p_commish_pin) then return jsonb_build_object('ok',false,'error','Commissioner authorization failed.'); end if;
  if jsonb_typeof(p_team_ids)<>'array' or jsonb_array_length(p_team_ids)<>12 then return jsonb_build_object('ok',false,'error','Draft order must contain exactly 12 teams.'); end if;
  select count(*),count(distinct e.value) into v_count,v_distinct from jsonb_array_elements_text(p_team_ids) e join public.teams t on t.id=e.value::uuid and t.room_id=v_room;
  if v_count<>12 or v_distinct<>12 then return jsonb_build_object('ok',false,'error','Draft order must contain each room team exactly once.'); end if;
  delete from public.supplemental_order where room_id=v_room;
  insert into public.supplemental_order(room_id,slot,team_id)
  select v_room,ord,e.value::uuid from jsonb_array_elements_text(p_team_ids) with ordinality e(value,ord);
  return jsonb_build_object('ok',true);
end; $$;

create or replace function public._supp_select(p_room_id uuid,p_team_id uuid,p_player_id uuid,p_is_commish boolean default false)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_s public.supplemental_settings%rowtype; v_p public.supplemental_players%rowtype; v_current uuid;
begin
  select * into v_s from public.supplemental_settings where room_id=p_room_id for update;
  if v_s.status<>'live' or v_s.stage<>'pick' then return jsonb_build_object('ok',false,'error','The draft is not currently accepting a selection.'); end if;
  if v_s.stage_ends_at is null or now()>=v_s.stage_ends_at then return jsonb_build_object('ok',false,'error','The pick clock has expired.'); end if;
  v_current:=public._supp_team_for_pick(p_room_id,v_s.current_pick_no);
  if v_current is null or p_team_id<>v_current then return jsonb_build_object('ok',false,'error','That team is not on the clock.'); end if;
  select * into v_p from public.supplemental_players where id=p_player_id and room_id=p_room_id for update;
  if v_p.id is null or v_p.status<>'available' then return jsonb_build_object('ok',false,'error','That player is no longer available.'); end if;
  update public.supplemental_settings set stage='challenge',stage_ends_at=now()+make_interval(secs=>challenge_seconds),selected_player_id=v_p.id,selected_by_team_id=p_team_id,active_bid=0,active_bidder_team_id=null,pause_remaining_seconds=null,updated_at=now() where room_id=p_room_id;
  return jsonb_build_object('ok',true,'player',v_p.name,'challenge_seconds',v_s.challenge_seconds);
end; $$;

create or replace function public.supp_select_player(p_room_code text,p_team_id uuid,p_pin text,p_player_id uuid)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_room uuid;
begin
  select id into v_room from public.rooms where code=p_room_code;
  if v_room is null or not public._valid_team_pin(p_team_id,p_pin) then return jsonb_build_object('ok',false,'error','Team authorization failed.'); end if;
  return public._supp_select(v_room,p_team_id,p_player_id,false);
end; $$;

create or replace function public.supp_commish_select_player(p_room_code text,p_commish_pin text,p_player_id uuid)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_room uuid; v_s public.supplemental_settings%rowtype; v_team uuid;
begin
  select id into v_room from public.rooms where code=p_room_code;
  if v_room is null or not public._valid_commish_pin(v_room,p_commish_pin) then return jsonb_build_object('ok',false,'error','Commissioner authorization failed.'); end if;
  select * into v_s from public.supplemental_settings where room_id=v_room;
  v_team:=public._supp_team_for_pick(v_room,v_s.current_pick_no);
  return public._supp_select(v_room,v_team,p_player_id,true);
end; $$;

create or replace function public.supp_challenge(p_room_code text,p_team_id uuid,p_pin text,p_mode text default 'open')
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_room uuid; v_s public.supplemental_settings%rowtype; v_p public.supplemental_players%rowtype; v_t public.teams%rowtype; v_next integer;
begin
  select id into v_room from public.rooms where code=p_room_code;
  if v_room is null or not public._valid_team_pin(p_team_id,p_pin) then return jsonb_build_object('ok',false,'error','Team authorization failed.'); end if;
  select * into v_s from public.supplemental_settings where room_id=v_room for update;
  if v_s.status<>'live' or v_s.stage not in ('challenge','rights_auction') or v_s.selected_player_id is null then return jsonb_build_object('ok',false,'error','There is no challenge opportunity right now.'); end if;
  if v_s.stage_ends_at is null or now()>=v_s.stage_ends_at then return jsonb_build_object('ok',false,'error','The challenge/auction clock has expired.'); end if;
  if p_team_id=v_s.selected_by_team_id and v_s.stage='challenge' then return jsonb_build_object('ok',false,'error','The selecting team cannot challenge its own selection.'); end if;
  select * into v_p from public.supplemental_players where id=v_s.selected_player_id;
  select * into v_t from public.teams where id=p_team_id and room_id=v_room for update;
  if p_mode='rights' then
    if v_s.stage<>'challenge' then return jsonb_build_object('ok',false,'error','Rookie rights can only initiate during the challenge window.'); end if;
    if v_p.rights_team_id is null or v_p.rights_team_id<>p_team_id then return jsonb_build_object('ok',false,'error','Your team does not hold rookie rights for this player.'); end if;
    if v_t.remaining_budget<2 then return jsonb_build_object('ok',false,'error','You need at least 2 bid dollars to use rookie rights.'); end if;
    update public.supplemental_settings set stage='rights_auction',active_bid=2,active_bidder_team_id=p_team_id,stage_ends_at=now()+make_interval(secs=>auction_seconds),updated_at=now() where room_id=v_room;
    insert into public.supplemental_bids(room_id,pick_no,player_id,team_id,amount,kind) values(v_room,v_s.current_pick_no,v_p.id,p_team_id,2,'rights');
    return jsonb_build_object('ok',true,'mode','rights','bid',2);
  end if;
  if v_s.stage='challenge' then
    v_next:=6;
  else
    if p_team_id in (v_s.selected_by_team_id,v_p.rights_team_id) then return jsonb_build_object('ok',false,'error','Only a third team can convert the rights auction to open bidding.'); end if;
    v_next:=greatest(6,v_s.active_bid+1);
  end if;
  if v_t.remaining_budget<v_next then return jsonb_build_object('ok',false,'error','You do not have enough bid dollars.'); end if;
  update public.supplemental_settings set stage='auction',active_bid=v_next,active_bidder_team_id=p_team_id,stage_ends_at=now()+make_interval(secs=>auction_seconds),updated_at=now() where room_id=v_room;
  insert into public.supplemental_bids(room_id,pick_no,player_id,team_id,amount,kind) values(v_room,v_s.current_pick_no,v_p.id,p_team_id,v_next,'open');
  return jsonb_build_object('ok',true,'mode','open','bid',v_next);
end; $$;

create or replace function public.supp_bid(p_room_code text,p_team_id uuid,p_pin text)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_room uuid; v_s public.supplemental_settings%rowtype; v_p public.supplemental_players%rowtype; v_t public.teams%rowtype; v_next integer; v_kind text;
begin
  select id into v_room from public.rooms where code=p_room_code;
  if v_room is null or not public._valid_team_pin(p_team_id,p_pin) then return jsonb_build_object('ok',false,'error','Team authorization failed.'); end if;
  select * into v_s from public.supplemental_settings where room_id=v_room for update;
  if v_s.status<>'live' or v_s.stage not in ('auction','rights_auction') then return jsonb_build_object('ok',false,'error','There is no live Supplemental auction.'); end if;
  if v_s.stage_ends_at is null or now()>=v_s.stage_ends_at then return jsonb_build_object('ok',false,'error','That auction has expired.'); end if;
  if v_s.active_bidder_team_id=p_team_id then return jsonb_build_object('ok',false,'error','You already have the high bid.'); end if;
  select * into v_p from public.supplemental_players where id=v_s.selected_player_id;
  if v_s.stage='rights_auction' and p_team_id not in (v_s.selected_by_team_id,v_p.rights_team_id) then return jsonb_build_object('ok',false,'error','This is a head-to-head rookie-rights auction. Use Open to All to enter as a third team.'); end if;
  select * into v_t from public.teams where id=p_team_id and room_id=v_room for update;
  v_next:=v_s.active_bid+1;
  if v_t.remaining_budget<v_next then return jsonb_build_object('ok',false,'error','You do not have enough bid dollars.'); end if;
  v_kind:=case when v_s.stage='rights_auction' then 'rights' else 'open' end;
  update public.supplemental_settings set active_bid=v_next,active_bidder_team_id=p_team_id,stage_ends_at=now()+make_interval(secs=>auction_seconds),updated_at=now() where room_id=v_room;
  insert into public.supplemental_bids(room_id,pick_no,player_id,team_id,amount,kind) values(v_room,v_s.current_pick_no,v_p.id,p_team_id,v_next,v_kind);
  return jsonb_build_object('ok',true,'bid',v_next);
end; $$;

create or replace function public.supp_finalize_if_expired(p_room_code text)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_room uuid; v_s public.supplemental_settings%rowtype; v_picker uuid; v_winner uuid; v_price integer; v_round integer; v_outcome text; v_team public.teams%rowtype;
begin
  select id into v_room from public.rooms where code=p_room_code;
  if v_room is null then return jsonb_build_object('ok',false,'error','Room not found.'); end if;
  select * into v_s from public.supplemental_settings where room_id=v_room for update;
  if v_s.status<>'live' or v_s.stage_ends_at is null or now()<v_s.stage_ends_at then return jsonb_build_object('ok',true,'finalized',false); end if;
  if v_s.stage='pick' then
    update public.supplemental_settings set status='paused',stage_ends_at=null,pause_remaining_seconds=0,updated_at=now() where room_id=v_room;
    return jsonb_build_object('ok',true,'finalized',true,'expired_pick',true);
  end if;
  if v_s.selected_player_id is null then return jsonb_build_object('ok',false,'error','Selected player state is missing.'); end if;
  v_picker:=v_s.selected_by_team_id;
  v_round:=((v_s.current_pick_no-1)/12)+1;
  if v_s.stage='challenge' then
    v_winner:=v_picker; v_price:=0; v_outcome:='free';
  elsif v_s.stage in ('auction','rights_auction') then
    v_winner:=v_s.active_bidder_team_id; v_price:=v_s.active_bid; v_outcome:=case when v_s.stage='rights_auction' then 'rights_auction' else 'open_auction' end;
    if v_winner is null or v_price<1 then return jsonb_build_object('ok',false,'error','Auction winner state is missing.'); end if;
    select * into v_team from public.teams where id=v_winner for update;
    if v_team.remaining_budget<v_price then return jsonb_build_object('ok',false,'error','Winning team no longer has enough bid dollars.'); end if;
    update public.teams set remaining_budget=remaining_budget-v_price where id=v_winner;
  else
    return jsonb_build_object('ok',false,'error','This stage cannot be finalized.');
  end if;
  update public.supplemental_players set status='drafted',drafted_team_id=v_winner,drafted_price=v_price where id=v_s.selected_player_id and status='available';
  if not found then return jsonb_build_object('ok',false,'error','Selected player is no longer available.'); end if;
  insert into public.supplemental_picks(room_id,pick_no,round,selecting_team_id,player_id,winner_team_id,price,outcome)
  values(v_room,v_s.current_pick_no,v_round,v_picker,v_s.selected_player_id,v_winner,v_price,v_outcome);
  perform public._supp_advance(v_room);
  return jsonb_build_object('ok',true,'finalized',true,'winner_team_id',v_winner,'price',v_price,'outcome',v_outcome);
end; $$;

create or replace function public.supp_commish_undo_last_pick(p_room_code text,p_commish_pin text)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_room uuid; v_pick public.supplemental_picks%rowtype; v_s public.supplemental_settings%rowtype;
begin
  select id into v_room from public.rooms where code=p_room_code;
  if v_room is null or not public._valid_commish_pin(v_room,p_commish_pin) then return jsonb_build_object('ok',false,'error','Commissioner authorization failed.'); end if;
  select * into v_pick from public.supplemental_picks where room_id=v_room order by pick_no desc limit 1 for update;
  if v_pick.id is null then return jsonb_build_object('ok',false,'error','There is no Supplemental pick to undo.'); end if;
  if v_pick.price>0 then update public.teams set remaining_budget=remaining_budget+v_pick.price where id=v_pick.winner_team_id; end if;
  update public.supplemental_players set status='available',drafted_team_id=null,drafted_price=null where id=v_pick.player_id;
  delete from public.supplemental_bids where room_id=v_room and pick_no=v_pick.pick_no;
  delete from public.supplemental_picks where id=v_pick.id;
  select * into v_s from public.supplemental_settings where room_id=v_room for update;
  update public.supplemental_settings set status='live',current_pick_no=v_pick.pick_no,stage='pick',stage_ends_at=now()+make_interval(secs=>pick_seconds),pause_remaining_seconds=null,selected_player_id=null,selected_by_team_id=null,active_bid=0,active_bidder_team_id=null,updated_at=now() where room_id=v_room;
  return jsonb_build_object('ok',true,'pick_no',v_pick.pick_no);
end; $$;

create or replace function public.supp_commish_reset(p_room_code text,p_commish_pin text)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_room uuid; rec record;
begin
  select id into v_room from public.rooms where code=p_room_code;
  if v_room is null or not public._valid_commish_pin(v_room,p_commish_pin) then return jsonb_build_object('ok',false,'error','Commissioner authorization failed.'); end if;
  -- Refund ONLY bid dollars spent in Supplemental, preserving the Phase 1 auction balances.
  for rec in select winner_team_id,sum(price)::integer refund from public.supplemental_picks where room_id=v_room and price>0 group by winner_team_id loop
    update public.teams set remaining_budget=remaining_budget+rec.refund where id=rec.winner_team_id;
  end loop;
  delete from public.supplemental_bids where room_id=v_room;
  delete from public.supplemental_picks where room_id=v_room;
  update public.supplemental_players set status='available',drafted_team_id=null,drafted_price=null where room_id=v_room;
  update public.supplemental_settings set status='setup',current_pick_no=1,stage='pick',stage_ends_at=null,pause_remaining_seconds=null,selected_player_id=null,selected_by_team_id=null,active_bid=0,active_bidder_team_id=null,updated_at=now() where room_id=v_room;
  return jsonb_build_object('ok',true);
end; $$;

-- Internal helper functions stay private.
revoke all on function public._supp_team_for_pick(uuid,integer) from public,anon,authenticated;
revoke all on function public._supp_advance(uuid) from public,anon,authenticated;
revoke all on function public._supp_select(uuid,uuid,uuid,boolean) from public,anon,authenticated;

grant execute on function public.supp_commish_start(text,text) to anon,authenticated;
grant execute on function public.supp_commish_pause(text,text) to anon,authenticated;
grant execute on function public.supp_commish_resume(text,text) to anon,authenticated;
grant execute on function public.supp_commish_add_time(text,text,integer) to anon,authenticated;
grant execute on function public.supp_commish_update_settings(text,text,integer,integer,integer) to anon,authenticated;
grant execute on function public.supp_commish_set_order(text,text,jsonb) to anon,authenticated;
grant execute on function public.supp_select_player(text,uuid,text,uuid) to anon,authenticated;
grant execute on function public.supp_commish_select_player(text,text,uuid) to anon,authenticated;
grant execute on function public.supp_challenge(text,uuid,text,text) to anon,authenticated;
grant execute on function public.supp_bid(text,uuid,text) to anon,authenticated;
grant execute on function public.supp_finalize_if_expired(text) to anon,authenticated;
grant execute on function public.supp_commish_undo_last_pick(text,text) to anon,authenticated;
grant execute on function public.supp_commish_reset(text,text) to anon,authenticated;

-- Realtime for all Phase 2 state.
do $$ begin
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='auction_rights_transfers') then alter publication supabase_realtime add table public.auction_rights_transfers; end if;
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='supplemental_players') then alter publication supabase_realtime add table public.supplemental_players; end if;
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='supplemental_settings') then alter publication supabase_realtime add table public.supplemental_settings; end if;
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='supplemental_order') then alter publication supabase_realtime add table public.supplemental_order; end if;
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='supplemental_picks') then alter publication supabase_realtime add table public.supplemental_picks; end if;
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='supplemental_bids') then alter publication supabase_realtime add table public.supplemental_bids; end if;
end $$;

commit;

-- Sanity-check result. Expected: 12 order slots, 202-ish available players (may vary if this source snapshot is edited), 45/10/30 timers.
select s.status,s.current_pick_no,s.pick_seconds,s.challenge_seconds,s.auction_seconds,
 (select count(*) from public.supplemental_order o where o.room_id=s.room_id) as order_slots,
 (select count(*) from public.supplemental_players p where p.room_id=s.room_id and p.status='available') as available_players
from public.supplemental_settings s join public.rooms r on r.id=s.room_id where r.code='GLSK26';
